from pathlib import Path

path = Path('index.html')
text = path.read_text(encoding='utf-8')

# Remove top WebM/GIF buttons so export lives only in Import / Export tools.
text = text.replace('      <button class="btn small primary" id="btn-export-webm-top" style="flex:0 0 auto;" title="Export the current animation as a WebM file">Export WebM</button>\n', '')
text = text.replace('      <button class="btn small primary" id="btn-export-gif-top" style="flex:0 0 auto;" title="Export the current animation as an animated GIF">Export GIF</button>\n', '')

# Keep the old recorder controls available to JS, but hide their old sidebar export group.
old_export = '''  <div class="group">\n    <h2>Export</h2>\n    <div class="row">\n      <label>Duration (s)</label>\n      <input type="number" id="inp-duration" value="6" min="1" max="120" step="1">\n    </div>\n    <div class="btn-row" style="margin-top:4px;">\n      <button class="btn primary" id="btn-record">Export WebM</button>\n      <button class="btn primary" id="btn-export-gif">Export GIF</button>\n      <button class="btn danger" id="btn-stop" disabled>Stop</button>\n    </div>\n    <a id="download-link" download="luke-animate.webm">Download will appear here</a>\n    <div id="status">Format: <b id="status-format">—</b></div>\n    <div class="hint">\n      Set the duration here (it stays in sync with the Timeline below — changing either one updates both). Stage size, frame rate and background are controlled from the floating <b>Stage Settings</b> panel. Export is always WebM. Transparent export requires a browser that records canvas alpha in WebM.\n    </div>\n  </div>'''
hidden_export = '''  <div class="group" id="legacy-export-controls" style="display:none;">\n    <h2>Export</h2>\n    <div class="row">\n      <label>Duration (s)</label>\n      <input type="number" id="inp-duration" value="6" min="1" max="120" step="1">\n    </div>\n    <div class="btn-row" style="margin-top:4px;">\n      <button class="btn primary" id="btn-record">Export WebM</button>\n      <button class="btn primary" id="btn-export-gif">Export GIF</button>\n      <button class="btn danger" id="btn-stop" disabled>Stop</button>\n    </div>\n    <a id="download-link" download="luke-animate.webm">Download will appear here</a>\n    <div id="status">Format: <b id="status-format">—</b></div>\n  </div>'''
if old_export in text:
    text = text.replace(old_export, hidden_export, 1)

# Add unified export controls at top of Import / Export panel.
anchor = '''  <div class="devpanel" id="devpanel-import" style="display:none;">\n    <div class="hint" style="padding:12px 14px 0;">Export your Behaviours to share or back up, or bring some in three ways below.</div>\n    <div style="padding:10px 14px;">'''
replacement = '''  <div class="devpanel" id="devpanel-import" style="display:none;">\n    <div style="padding:12px 14px 0;">\n      <div class="group" id="unified-export-group" style="padding:0 0 14px;margin:0 0 12px;border-bottom:1px solid var(--line);">\n        <h2 style="margin-top:0;">Export Animation</h2>\n        <div class="row">\n          <label>Format</label>\n          <select id="sel-unified-export-format" style="flex:1;">\n            <option value="webm" selected>WebM</option>\n            <option value="gif">GIF</option>\n            <option value="webp">Animated WebP</option>\n            <option value="apng">APNG</option>\n            <option value="avif">Animated AVIF</option>\n            <option value="mpg">MPG / MPEG</option>\n          </select>\n        </div>\n        <div class="row">\n          <label>Duration (s)</label>\n          <input type="number" id="inp-unified-export-duration" value="6" min="1" max="120" step="1" style="flex:1;">\n        </div>\n        <label class="toggle-line" id="unified-export-transparency-row"><input type="checkbox" id="chk-unified-export-transparent" checked> Transparent background</label>\n        <div class="hint" id="unified-export-format-note" style="padding:6px 0 8px;">WebM can preserve transparency when VP9 alpha recording is supported by the browser.</div>\n        <div class="btn-row">\n          <button class="btn primary" id="btn-unified-export" style="flex:1;">Export</button>\n          <button class="btn danger" id="btn-unified-export-stop" disabled>Stop</button>\n        </div>\n        <div id="unified-export-progress" class="audio-filename" style="margin-top:8px;">Ready.</div>\n      </div>\n      <div class="hint" style="padding:0 0 8px;">Export your Behaviours to share or back up, or bring some in three ways below.</div>\n    </div>\n    <div style="padding:0 14px 10px;">'''
if 'id="sel-unified-export-format"' not in text:
    if anchor not in text:
        raise SystemExit('Import / Export panel anchor not found')
    text = text.replace(anchor, replacement, 1)

# Add JS for unified controls just after legacy export element declarations.
js_anchor = '''  const statusFormat = document.getElementById('status-format');\n'''
js_insert = '''  const statusFormat = document.getElementById('status-format');\n  const unifiedExportFormat = document.getElementById('sel-unified-export-format');\n  const unifiedExportDuration = document.getElementById('inp-unified-export-duration');\n  const unifiedExportTransparent = document.getElementById('chk-unified-export-transparent');\n  const unifiedExportTransparencyRow = document.getElementById('unified-export-transparency-row');\n  const unifiedExportFormatNote = document.getElementById('unified-export-format-note');\n  const unifiedExportButton = document.getElementById('btn-unified-export');\n  const unifiedExportStop = document.getElementById('btn-unified-export-stop');\n  const unifiedExportProgress = document.getElementById('unified-export-progress');\n  let unifiedFFmpeg = null;\n  let unifiedFFmpegLoading = null;\n\n  function unifiedFormatSupportsTransparency(format){\n    return ['webm','gif','webp','apng','avif'].includes(format);\n  }\n\n  function syncUnifiedExportUI(){\n    if(!unifiedExportFormat) return;\n    const format = unifiedExportFormat.value;\n    const alpha = unifiedFormatSupportsTransparency(format);\n    if(unifiedExportTransparencyRow) unifiedExportTransparencyRow.style.opacity = alpha ? '1' : '.45';\n    if(unifiedExportTransparent) unifiedExportTransparent.disabled = !alpha;\n    if(!alpha && unifiedExportTransparent) unifiedExportTransparent.checked = false;\n    const notes = {\n      webm:'WebM uses Luke Animate’s existing deterministic recorder. Transparency depends on browser VP9 alpha support.',\n      gif:'GIF supports 1-bit transparency. Soft alpha edges are reduced to transparent/opaque pixels.',\n      webp:'Animated WebP supports full alpha transparency.',\n      apng:'APNG supports full alpha transparency.',\n      avif:'Animated AVIF supports alpha, but requires an AV1-capable browser encoder build.',\n      mpg:'MPG / MPEG does not support transparency; the stage background is flattened.'\n    };\n    if(unifiedExportFormatNote) unifiedExportFormatNote.textContent = notes[format] || '';\n  }\n\n  async function loadUnifiedFFmpeg(){\n    if(unifiedFFmpeg) return unifiedFFmpeg;\n    if(unifiedFFmpegLoading) return unifiedFFmpegLoading;\n    unifiedFFmpegLoading = (async()=>{\n      if(!window.FFmpeg){\n        await new Promise((resolve,reject)=>{\n          const script=document.createElement('script');\n          script.src='https://unpkg.com/@ffmpeg/ffmpeg@0.11.6/dist/ffmpeg.min.js';\n          script.onload=resolve; script.onerror=()=>reject(new Error('Could not load FFmpeg encoder.'));\n          document.head.appendChild(script);\n        });\n      }\n      const ff=FFmpeg.createFFmpeg({\n        log:false,\n        mainName:'main',\n        corePath:'https://unpkg.com/@ffmpeg/core-st@0.11.1/dist/ffmpeg-core.js'\n      });\n      await ff.load();\n      unifiedFFmpeg=ff;\n      return ff;\n    })();\n    try{return await unifiedFFmpegLoading;}finally{unifiedFFmpegLoading=null;}\n  }\n\n  function canvasPNGBlob(sourceCanvas, transparent){\n    return new Promise((resolve,reject)=>{\n      const c=document.createElement('canvas'); c.width=W; c.height=H;\n      const cx=c.getContext('2d',{alpha:true});\n      if(!transparent){ cx.fillStyle=stageColor||'#ffffff'; cx.fillRect(0,0,W,H); }\n      cx.drawImage(sourceCanvas,0,0,W,H);\n      c.toBlob(blob=>blob?resolve(blob):reject(new Error('Could not create export frame.')),'image/png');\n    });\n  }\n\n  async function exportFrameSequenceWithFFmpeg(format, transparent){\n    const fps=Math.max(1,getTimelineFPS());\n    const duration=Math.max(.001,timelineDuration);\n    const totalFrames=Math.max(1,Math.round(duration*fps));\n    const restorePlaying=playing, restoreTime=t;\n    const restoreExportState={active:exportPlayback.active,fps:exportPlayback.fps,duration:exportPlayback.duration,totalFrames:exportPlayback.totalFrames,currentFrameIndex:exportPlayback.currentFrameIndex,recorderStarted:exportPlayback.recorderStarted};\n    let clean=false;\n    const ff=await loadUnifiedFFmpeg();\n    const frameNames=[];\n    try{\n      beginCleanWebMExportView(); clean=true; exportPlayback.active=true; exportPlayback.fps=fps; exportPlayback.duration=duration; exportPlayback.totalFrames=totalFrames; exportPlayback.recorderStarted=false; playing=false; layers.forEach(layer=>layer.state={});\n      for(let i=0;i<totalFrames;i+=1){\n        exportPlayback.currentFrameIndex=i; t=i/fps; syncActiveSceneFrameForTime(t,true); await waitAnimationFrames(2);\n        const blob=await canvasPNGBlob(canvas,transparent);\n        const name=`frame${String(i).padStart(6,'0')}.png`; frameNames.push(name); ff.FS('writeFile',name,new Uint8Array(await blob.arrayBuffer()));\n        if(unifiedExportProgress) unifiedExportProgress.textContent=`Preparing frame ${i+1} of ${totalFrames}…`;\n        if(i%2===1) await new Promise(r=>setTimeout(r,0));\n      }\n      let out='luke-animate.'+format;\n      let args=['-framerate',String(fps),'-i','frame%06d.png'];\n      if(format==='webp') args.push('-loop','0','-c:v','libwebp','-lossless','0','-q:v','80','-pix_fmt',transparent?'yuva420p':'yuv420p',out);\n      else if(format==='apng') args.push('-plays','0','-f','apng',out);\n      else if(format==='mpg') args.push('-c:v','mpeg2video','-q:v','3','-pix_fmt','yuv420p',out);\n      else if(format==='avif') args.push('-c:v','libaom-av1','-crf','28','-b:v','0',out);\n      else throw new Error('Unsupported export format: '+format);\n      if(unifiedExportProgress) unifiedExportProgress.textContent='Encoding '+format.toUpperCase()+'…';\n      await ff.run(...args);\n      const data=ff.FS('readFile',out);\n      const mime={webp:'image/webp',apng:'image/apng',avif:'image/avif',mpg:'video/mpeg'}[format]||'application/octet-stream';\n      const blob=new Blob([data.buffer],{type:mime}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=out; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(url),60000);\n      try{ff.FS('unlink',out);}catch(e){}\n      if(unifiedExportProgress) unifiedExportProgress.textContent='Export complete.';\n    }finally{\n      frameNames.forEach(name=>{try{ff.FS('unlink',name);}catch(e){}});\n      exportPlayback.active=restoreExportState.active; exportPlayback.fps=restoreExportState.fps; exportPlayback.duration=restoreExportState.duration; exportPlayback.totalFrames=restoreExportState.totalFrames; exportPlayback.currentFrameIndex=restoreExportState.currentFrameIndex; exportPlayback.recorderStarted=restoreExportState.recorderStarted; playing=restorePlaying; t=restoreTime; syncActiveSceneFrameForTime(t,true); if(clean) restoreCleanWebMExportView();\n    }\n  }\n\n  async function runUnifiedExport(){\n    if(!unifiedExportFormat || !unifiedExportButton) return;\n    const format=unifiedExportFormat.value;\n    const transparent=!!(unifiedExportTransparent && unifiedExportTransparent.checked && unifiedFormatSupportsTransparency(format));\n    if(unifiedExportDuration && document.getElementById('inp-duration')){ document.getElementById('inp-duration').value=unifiedExportDuration.value; document.getElementById('inp-duration').dispatchEvent(new Event('change',{bubbles:true})); }\n    unifiedExportButton.disabled=true; if(unifiedExportStop) unifiedExportStop.disabled=false; if(unifiedExportProgress) unifiedExportProgress.textContent='Starting export…';\n    try{\n      if(format==='webm'){ if(btnRecord && !btnRecord.disabled) btnRecord.click(); if(unifiedExportProgress) unifiedExportProgress.textContent='WebM export started…'; return; }\n      if(format==='gif'){ await exportAnimatedGIF(); if(unifiedExportProgress) unifiedExportProgress.textContent='GIF export complete.'; return; }\n      await exportFrameSequenceWithFFmpeg(format,transparent);\n    }catch(error){\n      console.error('Unified export failed:',error);\n      if(unifiedExportProgress) unifiedExportProgress.textContent='Export failed: '+(error&&error.message?error.message:error);\n      alert('Export failed: '+(error&&error.message?error.message:error));\n    }finally{ unifiedExportButton.disabled=false; if(unifiedExportStop) unifiedExportStop.disabled=true; }\n  }\n\n  if(unifiedExportFormat){ unifiedExportFormat.addEventListener('change',syncUnifiedExportUI); syncUnifiedExportUI(); }\n  if(unifiedExportDuration){ unifiedExportDuration.value=String(Math.max(1,Math.round(timelineDuration||6))); }\n  if(unifiedExportButton) unifiedExportButton.addEventListener('click',runUnifiedExport);\n  if(unifiedExportStop) unifiedExportStop.addEventListener('click',()=>{ if(btnStop && !btnStop.disabled) btnStop.click(); try{if(unifiedFFmpeg) unifiedFFmpeg.exit();}catch(e){} unifiedFFmpeg=null; if(unifiedExportProgress) unifiedExportProgress.textContent='Export stopped.'; });\n'''
if 'const unifiedExportFormat =' not in text:
    if js_anchor not in text:
        raise SystemExit('Export JS anchor not found')
    text = text.replace(js_anchor, js_insert, 1)

# Guard references to removed top toolbar buttons.
text = text.replace("const btnExportWebMTop = document.getElementById('btn-export-webm-top');", "const btnExportWebMTop = document.getElementById('btn-export-webm-top');")
text = text.replace("const btnExportGIFTop = document.getElementById('btn-export-gif-top');", "const btnExportGIFTop = document.getElementById('btn-export-gif-top');")

path.write_text(text, encoding='utf-8')
print('Unified export added to Import / Export tools.')
